import pytest

@pytest.mark.parametrize(
    "status, expected_status_code",
    [
        ("available", 200),  # Valid status
        ("pending", 200),    # Valid status
        ("sold", 200),       # Valid status
        ("invalid", 400),    # Invalid status
        (None, 200),         # Default status (no status value provided)
    ],
)
def test_find_pets_by_status(api_client, valid_api_key, status, expected_status_code):
    """
    Test the /pet/findByStatus endpoint with various status values.

    Covers:
    - Valid statuses (available, pending, sold)
    - Invalid status (invalid)
    - No status provided (default)
    - Valid and invalid API keys
    """
    headers = {"Authorization": f"Bearer {valid_api_key}"}

    params = {"status": status} if status else None
    response = api_client.get("/pet/findByStatus", headers=headers, params=params)

    assert response.status_code == expected_status_code, f"Unexpected status code: {response.status_code}"

    if expected_status_code == 200:
        # Validate response schema
        response_json = response.json()
        assert isinstance(response_json, list), "Response should be a list of pets."
        for pet in response_json:
            assert "name" in pet, "Each pet should have a 'name'."
            assert "photoUrls" in pet, "Each pet should have 'photoUrls'."
            assert isinstance(pet["photoUrls"], list), "'photoUrls' should be a list."
    elif expected_status_code == 400:
        assert "Invalid status value" in response.text, "Expected 'Invalid status value' error message."


